/* GENERATED by gen_hcon_vault.py -- models are generated.
   REF_BANK_BRANCH_IFSC
   anchor      : REF_BANK_BRANCH_IFSC   (kind: ref, origin: reference_table_is_its_own_key_space)
   track       : reference
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 4 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER REF_BANK_BRANCH_IFSC_HK
   hashdiff    : REF_BANK_BRANCH_IFSC_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('REF_BANK_BRANCH_IFSC|' || (REF_BANK_BRANCH_IFSC_BK__IFSC_CODE))) as REF_BANK_BRANCH_IFSC_HK
        , IFSC_CODE as IFSC_CODE
        , MICR_CODE as MICR_CODE
        , BRANCH_NAME as BRANCH_NAME
        , NEFT_STATUS as NEFT_ENABLED_INDICATOR
        , 'BJAZ_NEFT_IFSC_MASTER' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_neft_ifsc_master') }}
    where (nullif(trim(IFSC_CODE),'')) is not null
),

resolved as (
    select
        REF_BANK_BRANCH_IFSC_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then IFSC_CODE end) as IFSC_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then MICR_CODE end) as MICR_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then BRANCH_NAME end) as BRANCH_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then NEFT_ENABLED_INDICATOR end) as NEFT_ENABLED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by REF_BANK_BRANCH_IFSC_HK
),

hashed as (
    select
        *,
        case when IFSC_CODE is not null or MICR_CODE is not null or BRANCH_NAME is not null or NEFT_ENABLED_INDICATOR is not null
                     then md5(upper(coalesce(cast(IFSC_CODE as varchar), '') || '|' || coalesce(cast(MICR_CODE as varchar), '') || '|' || coalesce(cast(BRANCH_NAME as varchar), '') || '|' || coalesce(cast(NEFT_ENABLED_INDICATOR as varchar), '')))
                end as REF_BANK_BRANCH_IFSC_HASHDIFF
    from resolved
)

select * from hashed
where REF_BANK_BRANCH_IFSC_HK is not null
  and REF_BANK_BRANCH_IFSC_HASHDIFF is not null
